insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('RTL-301', 'Good at Picking Stock, Cannot Read the Shop''s Numbers', 'Founder Psychology', 'internal', 'The founder has an eye for what will sell and customers like the shop. What each square foot earns, what the slow stock is costing to hold, and which hours actually make money have never been worked out.', 5, 9, '["Good buying instinct, weak numbers", "Slow stock held indefinitely", "Does not know which hours earn", "Cannot say what the shop keeps"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["retail"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-301-1', (select problem_id from problems where problem_code = 'RTL-301'), 'Retail Numbers Never Learned', 'Knowledge', 'Nobody taught the founder to read stock turn, holding cost or what an hour of opening actually earns.', 0.77, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-301-2', (select problem_id from problems where problem_code = 'RTL-301'), 'The Shop Floor Is the Comfortable Place', 'Psychological', 'Serving customers and picking stock feel like the real job; the arithmetic keeps waiting.', 0.72, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-301-3', (select problem_id from problems where problem_code = 'RTL-301'), 'Slow Stock Not Faced', 'Behavioural', 'Unsold items are left on the shelf rather than marked down on a schedule, because doing so admits the buy was wrong.', 0.68, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-301-1', (select problem_id from problems where problem_code = 'RTL-301'), '["RC-RTL-301-1", "RC-RTL-301-2", "RC-RTL-301-3"]'::jsonb, 'Founder Leverage', 'Retail (offline & online) — Founder Skill Fit', '[]'::jsonb, '["List everything that has been on the shelf more than ninety days.", "Work out how much money is sitting in it.", "Mark it down on a written schedule and use the cash on what actually sells."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["Slow stock is cash you already spent, sitting still.", "A markdown schedule removes the decision from the emotion."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-301-2', (select problem_id from problems where problem_code = 'RTL-301'), '["RC-RTL-301-1", "RC-RTL-301-2", "RC-RTL-301-3"]'::jsonb, 'Founder Leverage', 'Retail (offline & online) — Founder Skill Fit', '[]'::jsonb, '["Work out what one hour of being open costs you, all in.", "Compare that to what each hour of the day actually takes.", "Change your opening hours where the two do not meet."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["Some of your opening hours are costing you money; find out which."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
