insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('RTL-302', 'The Founder Is Behind the Counter Every Day', 'Founder Psychology', 'internal', 'Serving, restocking, cashing up and covering absences fill every day. The work that would make the shop run without them, or open a second one, never begins.', 5, 9, '["Founder behind the counter daily", "Covers every absence personally", "No time for planning", "The same daily problems"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["retail"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-302-1', (select problem_id from problems where problem_code = 'RTL-302'), 'Covering Instead of Fixing', 'Behavioural', 'Each gap is filled by the founder personally, so the reason it keeps appearing is never worked on.', 0.76, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-302-2', (select problem_id from problems where problem_code = 'RTL-302'), 'No Hours Reserved', 'Operational', 'No time is protected for buying, planning or training, so only today''s trading gets attention.', 0.72, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-302-3', (select problem_id from problems where problem_code = 'RTL-302'), 'Being There Feels Like Standards', 'Psychological', 'The founder believes the shop only runs properly when they are in it, so stepping back feels like a risk.', 0.68, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-302-1', (select problem_id from problems where problem_code = 'RTL-302'), '["RC-RTL-302-1", "RC-RTL-302-2", "RC-RTL-302-3"]'::jsonb, 'Founder Leverage', 'Retail (offline & online) — Founder Time Use', '[]'::jsonb, '["Write down every time you had to step in for one month, and why.", "Group them and fix the biggest group -- a rota rule, a trained second person, a written opening list.", "Count the times again next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["If you are the backup for everything, you are the plan.", "Count before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-302-2', (select problem_id from problems where problem_code = 'RTL-302'), '["RC-RTL-302-1", "RC-RTL-302-2", "RC-RTL-302-3"]'::jsonb, 'Founder Leverage', 'Retail (offline & online) — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Train one person to open and close completely, from a written list."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["One person trained properly beats being present yourself."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
