insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('RTL-303', 'The Buying and the Supplier Terms Live in One Head', 'Founder Psychology', 'internal', 'What to order, how much, from whom and at what price is all the founder''s judgement, unwritten. Staff cannot order, cannot negotiate and cannot cover a buying trip.', 5, 9, '["Buying decisions all founder-made", "Supplier terms unwritten", "Staff cannot order anything", "Cannot cover a buying trip"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["retail"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-303-1', (select problem_id from problems where problem_code = 'RTL-303'), 'Buying Judgement Never Written', 'Knowledge', 'What to order and how much lives in the founder''s head and was never turned into rules anyone could apply.', 0.78, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-303-2', (select problem_id from problems where problem_code = 'RTL-303'), 'Relationships Not Transferred', 'Operational', 'Suppliers deal with the founder personally and nobody else has the terms or the standing.', 0.73, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-303-3', (select problem_id from problems where problem_code = 'RTL-303'), 'Holding It Feels Like Protecting Margin', 'Psychological', 'Keeping the terms private feels like protecting the shop''s margin, so writing them down feels like a loss.', 0.66, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-303-1', (select problem_id from problems where problem_code = 'RTL-303'), '["RC-RTL-303-1", "RC-RTL-303-2", "RC-RTL-303-3"]'::jsonb, 'Founder Leverage', 'Retail (offline & online) — Founder Dependency', '[]'::jsonb, '["Write the reorder rule for your top twenty items: at what shelf level, how many, from whom.", "Put it where staff can read it.", "Let someone else place the next order and check it afterwards."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["A reorder rule is buying judgement that survives your absence.", "Check the order afterwards, not before."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
