insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('RTL-304', 'Whoever Is On Shift Does Whatever Needs Doing', 'Team & Leadership', 'internal', 'Serving, restocking, displays and cash all land on whoever is present. Nobody owns any of them, so standards move with the rota and a missing job has nobody to ask about it.', 5, 9, '["Jobs follow the rota", "No owner for stock or displays", "Standards vary by shift", "Nobody accountable for a recurring miss"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["retail"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-304-1', (select problem_id from problems where problem_code = 'RTL-304'), 'Roles Never Set', 'Behavioural', 'The team was built as shifts to cover rather than jobs to own, so no task has a permanent owner.', 0.76, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-304-2', (select problem_id from problems where problem_code = 'RTL-304'), 'Everyone Does Everything', 'Psychological', 'A team where anyone does anything feels willing, which hides that nothing is owned.', 0.70, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-304-3', (select problem_id from problems where problem_code = 'RTL-304'), 'Handovers Unwritten', 'Operational', 'What must be true at the end of one shift for the next to start clean was never agreed.', 0.69, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
