insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('RTL-307', 'Talks About a Chain, Runs One Shop on Instinct', 'Strategy & Planning', 'internal', 'The founder describes several shops in a few years, and everything about this one depends on their judgement: the buying, the displays, the standards. Nothing being built now could be copied.', 5, 9, '["Talks chain, runs a one-off", "Nothing written to copy", "Standards live with the founder", "Second shop out of reach"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["retail"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-307-1', (select problem_id from problems where problem_code = 'RTL-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody asks whether today''s way of working could be repeated in another shop, so the gap grows quietly.', 0.78, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-307-2', (select problem_id from problems where problem_code = 'RTL-307'), 'Today''s Trading Decides Everything', 'Behavioural', 'Every choice is made for today''s takings and none asks whether it would copy.', 0.73, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-RTL-307-3', (select problem_id from problems where problem_code = 'RTL-307'), 'Goal Is a Number, Not a Description', 'Knowledge', 'The ambition is a count of shops rather than a list of what must be true to open one.', 0.67, 'internal', 'Stage 0→1', '["retail"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-307-1', (select problem_id from problems where problem_code = 'RTL-307'), '["RC-RTL-307-1", "RC-RTL-307-2", "RC-RTL-307-3"]'::jsonb, 'Strategic Focus', 'Retail (offline & online) — Plan and Vision', '[]'::jsonb, '["Write what must exist before you could open a second shop: buying rules, standards, training, numbers.", "Mark which exist today.", "Build the missing one that takes longest, starting now."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["A second shop needs written things, not more effort.", "Start with the slowest missing piece."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-RTL-307-2', (select problem_id from problems where problem_code = 'RTL-307'), '["RC-RTL-307-1", "RC-RTL-307-2", "RC-RTL-307-3"]'::jsonb, 'Strategic Focus', 'Retail (offline & online) — Plan and Vision', '[]'::jsonb, '["Take one decision you made this month and ask whether it works at three shops.", "If not, write what you would do instead.", "Do that instead, this month."]'::jsonb, '[3, 4, 5]'::jsonb, '["retail"]'::jsonb, '["Test the ambition against one real decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
