insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SPF-301', 'A Great Trainer Who Has Never Run a Business', 'Founder Psychology', 'internal', 'Members get real results and they say so. What a member is worth over the months they stay, what it costs to sign one up, and how many leave each month have never been worked out, so the gym feels busy and the bank account does not.', 5, 9, '["Great coaching, weak business numbers", "Does not know what a member is worth", "Cost of signing a member unknown", "Busy floor, thin bank account"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["sports_fitness"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-301-1', (select problem_id from problems where problem_code = 'SPF-301'), 'Membership Numbers Never Learned', 'Knowledge', 'Nobody taught the founder to work out what a member is worth over their life or how many leave each month.', 0.77, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-301-2', (select problem_id from problems where problem_code = 'SPF-301'), 'Coaching Is the Comfortable Work', 'Psychological', 'Being on the floor with members feels like the real job; the numbers feel like a distraction from it.', 0.72, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-301-3', (select problem_id from problems where problem_code = 'SPF-301'), 'A Full Floor Mistaken for Health', 'Behavioural', 'A busy gym is treated as a healthy business, so the people quietly leaving are never counted.', 0.68, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SPF-301-1', (select problem_id from problems where problem_code = 'SPF-301'), '["RC-SPF-301-1", "RC-SPF-301-2", "RC-SPF-301-3"]'::jsonb, 'Founder Leverage', 'Sports, Fitness & Wellness — Founder Skill Fit', '[]'::jsonb, '["Count how many members you had at the start of last month and how many are left.", "Work out how many left, as a share.", "Do that every month from now, before anything else."]'::jsonb, '[3, 4, 5]'::jsonb, '["sports_fitness"]'::jsonb, '["A gym that signs ten and loses nine is not growing, it is churning.", "One number, tracked monthly, beats a dashboard you never open."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SPF-301-2', (select problem_id from problems where problem_code = 'SPF-301'), '["RC-SPF-301-1", "RC-SPF-301-2", "RC-SPF-301-3"]'::jsonb, 'Founder Leverage', 'Sports, Fitness & Wellness — Founder Skill Fit', '[]'::jsonb, '["Work out what a member pays you in total before they leave.", "Work out what it cost to get them.", "If the second is bigger than the first, stop spending until it is not."]'::jsonb, '[3, 4, 5]'::jsonb, '["sports_fitness"]'::jsonb, '["You cannot outspend a member who leaves in two months."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
