insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SPF-306', 'Coaches Hired From the Member Base, On Enthusiasm', 'Team & Leadership', 'internal', 'Coaches come from among the members because they love the place. Real advantage, and it means nobody was assessed on whether they can actually coach a stranger, so quality varies by class.', 5, 9, '["Coaches hired from members", "Coaching ability not assessed", "Quality varies by class", "No written job description"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["sports_fitness"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-306-1', (select problem_id from problems where problem_code = 'SPF-306'), 'No Written Role or Test', 'Operational', 'Hiring starts from an enthusiastic member rather than from a written job with a way to test coaching ability.', 0.77, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-306-2', (select problem_id from problems where problem_code = 'SPF-306'), 'Enthusiasm Read as Capability', 'Behavioural', 'Because candidates love the gym, their ability to coach is assumed rather than checked.', 0.73, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-306-3', (select problem_id from problems where problem_code = 'SPF-306'), 'Nothing Learned Between Hires', 'Knowledge', 'Who turned out able to coach and why is never written down, so the pattern is never seen.', 0.67, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
