insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SPF-309', 'Why Members Leave Is Never Written Down', 'Strategy & Planning', 'internal', 'Which members left and why, which class time never filled, what last year''s January actually looked like — all in memory. So the same timetable mistake and the same drop-off happen again.', 5, 9, '["Leaving reasons not recorded", "Class attendance not tracked over time", "Seasonal patterns relearned", "Knowledge leaves with coaches"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["sports_fitness"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-309-1', (select problem_id from problems where problem_code = 'SPF-309'), 'Nothing Written Down', 'Operational', 'Why members left and how classes filled were never recorded, so the gym cannot learn from its own year.', 0.79, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-309-2', (select problem_id from problems where problem_code = 'SPF-309'), 'Memory Held by People', 'Knowledge', 'What the gym knows lives with the founder and a few coaches.', 0.73, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SPF-309-3', (select problem_id from problems where problem_code = 'SPF-309'), 'Asking Why Feels Uncomfortable', 'Psychological', 'Asking a leaving member why feels like inviting criticism, so it is not asked.', 0.67, 'internal', 'Stage 0→1', '["sports_fitness"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SPF-309-1', (select problem_id from problems where problem_code = 'SPF-309'), '["RC-SPF-309-1", "RC-SPF-309-2", "RC-SPF-309-3"]'::jsonb, 'Strategic Focus', 'Sports, Fitness & Wellness — What Gets Remembered', '[]'::jsonb, '["Ask every leaving member one question: what would have kept you?", "Write the answer down the same day.", "Read the list monthly and fix the reason that appears most."]'::jsonb, '[3, 4, 5]'::jsonb, '["sports_fitness"]'::jsonb, '["The leaving member is the only one who will tell you the truth.", "One question, asked every time, beats a survey nobody answers."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SPF-309-2', (select problem_id from problems where problem_code = 'SPF-309'), '["RC-SPF-309-1", "RC-SPF-309-2", "RC-SPF-309-3"]'::jsonb, 'Strategic Focus', 'Sports, Fitness & Wellness — What Gets Remembered', '[]'::jsonb, '["Write down attendance per class time, week by week, for a quarter.", "Cut or move the class times that never fill.", "Compare the next quarter."]'::jsonb, '[3, 4, 5]'::jsonb, '["sports_fitness"]'::jsonb, '["A class nobody attends costs a coach''s hour every week."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
