insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TEL-301', 'Knows the Network, Has Never Modelled the Payback', 'Founder Psychology', 'internal', 'The founder can design and build the network and it works. How long the capital takes to come back, how many subscribers a tower needs to break even, and what a subscriber is worth have never been modelled.', 5, 9, '["Strong technical, weak capital planning", "Payback period not modelled", "Break-even subscribers per site unknown", "Cannot say which sites earn"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["telecom"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-301-1', (select problem_id from problems where problem_code = 'TEL-301'), 'Capital Planning Never Learned', 'Knowledge', 'Nobody taught the founder to model payback on a capital build, so sites are chosen on coverage logic alone.', 0.77, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-301-2', (select problem_id from problems where problem_code = 'TEL-301'), 'The Network Is the Comfortable Work', 'Psychological', 'Designing and fixing the network feels like the real job; the financial model feels like someone else''s.', 0.72, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-301-3', (select problem_id from problems where problem_code = 'TEL-301'), 'Coverage Mistaken for Business', 'Behavioural', 'Expanding coverage is treated as progress, so sites are built before anyone asks what they need to earn.', 0.68, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TEL-301-1', (select problem_id from problems where problem_code = 'TEL-301'), '["RC-TEL-301-1", "RC-TEL-301-2", "RC-TEL-301-3"]'::jsonb, 'Founder Leverage', 'Telecommunications — Founder Skill Fit', '[]'::jsonb, '["Take your last three sites and work out how many subscribers each needs to break even.", "Compare that to how many each actually has.", "Do that calculation before approving the next site."]'::jsonb, '[3, 4, 5]'::jsonb, '["telecom"]'::jsonb, '["A site with coverage and no subscribers is a liability with an antenna on it.", "Do the sum before the build, not after."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TEL-301-2', (select problem_id from problems where problem_code = 'TEL-301'), '["RC-TEL-301-1", "RC-TEL-301-2", "RC-TEL-301-3"]'::jsonb, 'Founder Leverage', 'Telecommunications — Founder Skill Fit', '[]'::jsonb, '["Work out what one subscriber pays you in total before they leave.", "Work out what it cost to connect them.", "Use both numbers on your next expansion decision."]'::jsonb, '[3, 4, 5]'::jsonb, '["telecom"]'::jsonb, '["Expansion is a financial decision wearing an engineering costume."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
