insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TEL-302', 'The Founder Is Still the On-Call Engineer', 'Founder Psychology', 'internal', 'An outage, a faulty link, an angry business customer — the founder handles all of it personally because they are fastest. Regulatory filings, funding and building the team get what is left.', 5, 9, '["Founder handles every outage", "On call permanently", "Regulatory filings slipping", "No time for funding or team"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["telecom"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-302-1', (select problem_id from problems where problem_code = 'TEL-302'), 'Fastest Person Does the Work', 'Behavioural', 'The founder resolves faults quickest, so they keep landing on them and never transfer.', 0.76, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-302-2', (select problem_id from problems where problem_code = 'TEL-302'), 'No Hours Reserved', 'Operational', 'No time is protected for regulatory or funding work, so it happens only between outages.', 0.72, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-302-3', (select problem_id from problems where problem_code = 'TEL-302'), 'Being On Call Feels Like Reliability', 'Psychological', 'The founder believes uptime depends on their availability, which makes stepping back feel like risking the network.', 0.68, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TEL-302-1', (select problem_id from problems where problem_code = 'TEL-302'), '["RC-TEL-302-1", "RC-TEL-302-2", "RC-TEL-302-3"]'::jsonb, 'Founder Leverage', 'Telecommunications — Founder Time Use', '[]'::jsonb, '["Write down every fault for one month: what, how long, who fixed it.", "Group them and fix the cause of the biggest group.", "Count the minutes of downtime again next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["telecom"]'::jsonb, '["A fault that repeats is a design gap, not bad luck.", "Count the downtime before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
