insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TEL-303', 'The Network Design Is Only in the Founder''s Head', 'Founder Psychology', 'internal', 'How the network is configured, why it was built that way, and which link depends on which are all undocumented. Nobody else can plan a change or diagnose a fault safely.', 5, 9, '["Network design undocumented", "Dependencies known only to the founder", "Nobody else can plan a change safely", "Single point of failure is a person"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["telecom"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-303-1', (select problem_id from problems where problem_code = 'TEL-303'), 'Design Never Documented', 'Knowledge', 'The network topology and the reasons behind it live in the founder''s head and nowhere else.', 0.79, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-303-2', (select problem_id from problems where problem_code = 'TEL-303'), 'Nobody Else Trusted With a Change', 'Psychological', 'The founder fears an engineer bringing the network down, so nobody is allowed to plan one.', 0.72, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-303-3', (select problem_id from problems where problem_code = 'TEL-303'), 'No Handover Material', 'Operational', 'There is nothing an engineer could learn the design from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TEL-303-1', (select problem_id from problems where problem_code = 'TEL-303'), '["RC-TEL-303-1", "RC-TEL-303-2", "RC-TEL-303-3"]'::jsonb, 'Founder Leverage', 'Telecommunications — Founder Dependency', '[]'::jsonb, '["Draw the network as it actually is, including what depends on what.", "Have an engineer plan a small change from the drawing while you review it.", "Fix what the drawing got wrong, not what the engineer got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["telecom"]'::jsonb, '["An undocumented network has one point of failure and it is you.", "If they cannot plan from the drawing, the drawing is wrong."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TEL-303-2', (select problem_id from problems where problem_code = 'TEL-303'), '["RC-TEL-303-1", "RC-TEL-303-2", "RC-TEL-303-3"]'::jsonb, 'Founder Leverage', 'Telecommunications — Founder Dependency', '[]'::jsonb, '["Write down the three changes you would never let anyone else make, and why.", "For each, write what would have to be true for someone else to make it safely.", "Build that condition for one of them."]'::jsonb, '[3, 4, 5]'::jsonb, '["telecom"]'::jsonb, '["Name the condition rather than keeping the veto."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
