insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TEL-309', 'Every Outage Is Diagnosed From Scratch', 'Strategy & Planning', 'internal', 'What caused the last outage, which vendor''s equipment fails in the heat, what the regulator asked in the last filing — in memory and in individual inboxes. So the same fault is diagnosed again, expensively.', 5, 9, '["Outage causes not recorded", "Vendor failures not tracked", "Regulatory history in inboxes", "Knowledge leaves with engineers"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["telecom"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-309-1', (select problem_id from problems where problem_code = 'TEL-309'), 'Nothing Written Down', 'Operational', 'Faults, causes and fixes were never recorded, so the team rediscovers its own solutions.', 0.79, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-309-2', (select problem_id from problems where problem_code = 'TEL-309'), 'Memory Held by People', 'Knowledge', 'What the company knows lives with a few engineers and leaves when they do.', 0.74, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TEL-309-3', (select problem_id from problems where problem_code = 'TEL-309'), 'Recording a Fault Feels Like Blame', 'Psychological', 'Writing up an outage honestly feels like finding fault with the engineer on shift, so it is skipped.', 0.66, 'internal', 'Stage 0→1', '["telecom"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TEL-309-1', (select problem_id from problems where problem_code = 'TEL-309'), '["RC-TEL-309-1", "RC-TEL-309-2", "RC-TEL-309-3"]'::jsonb, 'Strategic Focus', 'Telecommunications — What Gets Remembered', '[]'::jsonb, '["Write one page per outage: what happened, what caused it, what fixed it, how long.", "Fill it in the day it is resolved, not at month end.", "Read the pages before the next design change."]'::jsonb, '[3, 4, 5]'::jsonb, '["telecom"]'::jsonb, '["A fix nobody wrote down will be rediscovered at full price.", "Write it the same day or it will not be written."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
