insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-301', 'Knows Cloth, Cannot Cost a Metre Properly', 'Founder Psychology', 'internal', 'The founder knows yarn, weave and finish better than any buyer. What a metre costs once wastage, rejected lots, power and idle loom time are counted has never been worked out, so a big order can lose money.', 5, 9, '["Deep product knowledge, weak costing", "Wastage not counted", "Idle loom time absorbed", "Cannot say which cloth earns"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-301-1', (select problem_id from problems where problem_code = 'TXT-301'), 'Costing Never Learned', 'Knowledge', 'Nobody taught the founder to cost a metre including wastage, rejects, power and idle machine time.', 0.77, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-301-2', (select problem_id from problems where problem_code = 'TXT-301'), 'The Mill Floor Is the Comfortable Place', 'Psychological', 'Solving a quality problem feels like real work; the costing feels like paperwork.', 0.72, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-301-3', (select problem_id from problems where problem_code = 'TXT-301'), 'Wastage Treated as Normal', 'Behavioural', 'Rejected lots are accepted as part of the trade rather than measured, so their real cost is never seen.', 0.68, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-301-1', (select problem_id from problems where problem_code = 'TXT-301'), '["RC-TXT-301-1", "RC-TXT-301-2", "RC-TXT-301-3"]'::jsonb, 'Founder Leverage', 'Textiles — Founder Skill Fit', '[]'::jsonb, '["Cost one product properly: yarn, wastage, rejects, power, labour, idle time.", "Compare that to what you quote.", "Do the same for your three highest-volume products before quoting again."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["A cloth that sells in volume and loses money is your biggest problem.", "Three products costed properly beats a whole range costed roughly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
