insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-302', 'The Founder Is On the Floor Solving Quality Problems', 'Founder Psychology', 'internal', 'A lot fails inspection, a loom is down, a dyeing batch is off shade. The founder is the best problem-solver in the mill and spends every day proving it, so the work of making the mill not need them never starts.', 5, 9, '["Founder solves quality problems daily", "Best problem-solver is the founder", "No time for planning or process", "The same defects recur"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-302-1', (select problem_id from problems where problem_code = 'TXT-302'), 'Fixing Instead of Preventing', 'Behavioural', 'Each defect is solved personally and the reason it keeps recurring is never worked on.', 0.77, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-302-2', (select problem_id from problems where problem_code = 'TXT-302'), 'No Hours Reserved', 'Operational', 'No time is protected for process or training, so only today''s defect gets attention.', 0.72, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-302-3', (select problem_id from problems where problem_code = 'TXT-302'), 'Being the Best Fixer Feels Necessary', 'Psychological', 'Because the founder genuinely is fastest, stepping back feels like accepting worse cloth.', 0.68, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-302-1', (select problem_id from problems where problem_code = 'TXT-302'), '["RC-TXT-302-1", "RC-TXT-302-2", "RC-TXT-302-3"]'::jsonb, 'Founder Leverage', 'Textiles — Founder Time Use', '[]'::jsonb, '["Write down every defect for one month: type, lot, cause if known.", "Group them and fix the cause of the biggest group.", "Count that group again next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["A defect that recurs is a process gap, not bad luck.", "Count before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-302-2', (select problem_id from problems where problem_code = 'TXT-302'), '["RC-TXT-302-1", "RC-TXT-302-2", "RC-TXT-302-3"]'::jsonb, 'Founder Leverage', 'Textiles — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Train one supervisor to handle the most common defect, with the steps written."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["Being fastest at a fix is the reason to write it down, not to keep doing it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
