insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-303', 'The Recipes and the Settings Are in the Founder''s Hands', 'Founder Psychology', 'internal', 'Dye recipes, loom settings, which yarn lot behaves how — all known by feel, none written. Quality moves with the founder''s presence and a second shift or unit is impossible.', 5, 9, '["Dye recipes not written down", "Loom settings known by feel", "Quality drops when the founder is away", "Second unit impossible"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-303-1', (select problem_id from problems where problem_code = 'TXT-303'), 'Recipes and Settings Never Written', 'Knowledge', 'Dye recipes and machine settings live in the founder''s hands, so consistency depends on them being present.', 0.78, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-303-2', (select problem_id from problems where problem_code = 'TXT-303'), 'Written Recipes Feel Like Giving It Away', 'Psychological', 'Documenting the recipes feels like handing over what makes the cloth good, so it is not done.', 0.73, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-303-3', (select problem_id from problems where problem_code = 'TXT-303'), 'No Training Material', 'Operational', 'There is nothing a supervisor could learn the standard from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-303-1', (select problem_id from problems where problem_code = 'TXT-303'), '["RC-TXT-303-1", "RC-TXT-303-2", "RC-TXT-303-3"]'::jsonb, 'Founder Leverage', 'Textiles — Founder Dependency', '[]'::jsonb, '["Write the recipe card for your three highest-volume shades: quantities, sequence, what to check.", "Have a supervisor run one from the card while you watch and say nothing.", "Fix what the card got wrong, not what the supervisor got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["If they cannot run it from the card, the card is wrong.", "Watching silently is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-303-2', (select problem_id from problems where problem_code = 'TXT-303'), '["RC-TXT-303-1", "RC-TXT-303-2", "RC-TXT-303-3"]'::jsonb, 'Founder Leverage', 'Textiles — Founder Dependency', '[]'::jsonb, '["Write down which yarn lot behaves how, and what you change for each.", "Put it where the setter works.", "Have them use it on the next lot without asking you."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["What is in your hands serves this shift; what is on paper serves every shift."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
