insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-304', 'Production and Quality Are the Same People', 'Team & Leadership', 'internal', 'The supervisor who runs the lot also passes it. Nobody checks independently, so a bad lot is discovered by the buyer rather than at the mill, which is the most expensive place to find it.', 5, 9, '["Lot run and passed by the same person", "No independent quality owner", "Bad lots found by the buyer", "Nobody accountable for rejects"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-304-1', (select problem_id from problems where problem_code = 'TXT-304'), 'Roles Never Set', 'Behavioural', 'The team grew by adding hands to production rather than by defining quality as a separate job.', 0.77, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-304-2', (select problem_id from problems where problem_code = 'TXT-304'), 'Self-Checking Feels Efficient', 'Psychological', 'Having the supervisor pass their own lot feels like trusting them, which hides that nobody checks independently.', 0.71, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-304-3', (select problem_id from problems where problem_code = 'TXT-304'), 'Handovers Unwritten', 'Operational', 'What must be checked before a lot is dispatched was never agreed, so it ships unchecked.', 0.69, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
