insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-305', 'Nobody Can Stop a Lot or Accept a Shade Variation', 'Team & Leadership', 'internal', 'A supervisor who sees an off shade cannot stop the lot, and nobody can accept a small variation. Both wait for the founder, so bad cloth keeps being made while the phone rings.', 5, 9, '["Supervisors cannot stop a lot", "Shade variations wait for the founder", "Bad cloth made while waiting", "No written tolerance authority"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-305-1', (select problem_id from problems where problem_code = 'TXT-305'), 'Limits Never Written', 'Operational', 'No one wrote down who may stop a lot or accept a variation, so nobody does either.', 0.78, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-305-2', (select problem_id from problems where problem_code = 'TXT-305'), 'Stopping Feels Expensive', 'Psychological', 'A stopped loom is a visible cost and rejected cloth is an invisible one, so nobody is empowered to stop.', 0.73, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-305-3', (select problem_id from problems where problem_code = 'TXT-305'), 'Judgement Not Trusted Yet', 'Behavioural', 'The founder has never seen a supervisor make these calls, so does not trust them to.', 0.67, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
