insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-308', 'New Looms, a Certification and a Big Order, Together', 'Strategy & Planning', 'internal', 'A machinery purchase, a compliance certification and a large new order are all live. The certification is what the large buyer will ask for, and it is getting the least attention.', 5, 9, '["Machinery purchase and certification together", "Large order in parallel", "Certification not prioritised", "Everything half-done"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-308-1', (select problem_id from problems where problem_code = 'TXT-308'), 'Nothing Ranked', 'Strategic', 'Work is listed rather than ordered, so a gating certification competes with a machinery purchase.', 0.78, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-308-2', (select problem_id from problems where problem_code = 'TXT-308'), 'Blocking Work Not Identified', 'Knowledge', 'Nobody wrote down which work gates the large order, so it is not treated differently.', 0.73, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-308-3', (select problem_id from problems where problem_code = 'TXT-308'), 'Buying Feels Like Progress', 'Psychological', 'New looms are visible progress; a certification file is invisible, so the looms get the attention.', 0.68, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-308-1', (select problem_id from problems where problem_code = 'TXT-308'), '["RC-TXT-308-1", "RC-TXT-308-2", "RC-TXT-308-3"]'::jsonb, 'Strategic Focus', 'Textiles — Prioritisation', '[]'::jsonb, '["Write down which single piece of work, if late, loses the largest order.", "Give it your best person and protect them from the rest.", "Delay whatever competes with it, and say so out loud."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["One gate first; everything behind it is waiting anyway.", "Say what is delayed or it continues quietly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TXT-308-2', (select problem_id from problems where problem_code = 'TXT-308'), '["RC-TXT-308-1", "RC-TXT-308-2", "RC-TXT-308-3"]'::jsonb, 'Strategic Focus', 'Textiles — Prioritisation', '[]'::jsonb, '["List everything running and what each needs from your scarcest person.", "Rank by what unblocks the most revenue.", "Pause the bottom two this week."]'::jsonb, '[3, 4, 5]'::jsonb, '["textiles"]'::jsonb, '["Rank by what unblocks, not by what is visible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
