insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TXT-309', 'Which Yarn Lot Failed Is Not Written Anywhere', 'Strategy & Planning', 'internal', 'Which supplier''s yarn broke on the loom, what setting fixed a finish problem last year, which buyer disputes every lot — all in a few heads. So the same problem is solved again at full price.', 5, 9, '["Yarn supplier problems not recorded", "Fixes rediscovered each time", "Buyer disputes not tracked", "Knowledge leaves with supervisors"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["textiles"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-309-1', (select problem_id from problems where problem_code = 'TXT-309'), 'Nothing Written Down', 'Operational', 'Yarn performance, defect causes and fixes were never recorded, so the mill rediscovers its own solutions.', 0.79, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-309-2', (select problem_id from problems where problem_code = 'TXT-309'), 'Memory Held by People', 'Knowledge', 'What the mill knows lives with a few experienced supervisors and walks out with them.', 0.74, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TXT-309-3', (select problem_id from problems where problem_code = 'TXT-309'), 'Recording a Fault Feels Like Blame', 'Psychological', 'Writing up a bad lot feels like finding fault with the shift, so it is skipped.', 0.66, 'internal', 'Stage 0→1', '["textiles"]'::jsonb) on conflict (root_cause_code) do nothing;
