insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-301', 'Great at Getting Parcels Delivered, Cannot Cost a Drop', 'Founder Psychology', 'internal', 'The founder can get anything anywhere and customers rely on it. What one delivery actually costs once the rider''s idle time, fuel, failed attempts and returns are counted has never been worked out, so a growing route can lose money.', 5, 9, '["Strong operations, weak cost per drop", "Failed attempts not costed", "Rider idle time absorbed", "Cannot say which route earns"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-301-1', (select problem_id from problems where problem_code = 'DLV-301'), 'Cost Per Drop Never Learned', 'Knowledge', 'Nobody taught the founder to cost a delivery including idle time, failed attempts and returns.', 0.77, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-301-2', (select problem_id from problems where problem_code = 'DLV-301'), 'Operations Is the Comfortable Work', 'Psychological', 'Solving today''s routing feels like real work; the arithmetic feels like paperwork.', 0.72, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-301-3', (select problem_id from problems where problem_code = 'DLV-301'), 'Volume Mistaken for Profit', 'Behavioural', 'More parcels is treated as a better month, so thin routes are never identified.', 0.68, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-301-1', (select problem_id from problems where problem_code = 'DLV-301'), '["RC-DLV-301-1", "RC-DLV-301-2", "RC-DLV-301-3"]'::jsonb, 'Founder Leverage', 'Transportation & Delivery — Founder Skill Fit', '[]'::jsonb, '["Take one route and cost every drop on it: fuel, rider time including waiting, failed attempts, returns.", "Compare that to what the customer pays per drop.", "Reprice or redesign the route before adding another."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["A busy rider is not the same as a profitable route.", "Failed attempts are the cost nobody counts."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-301-2', (select problem_id from problems where problem_code = 'DLV-301'), '["RC-DLV-301-1", "RC-DLV-301-2", "RC-DLV-301-3"]'::jsonb, 'Founder Leverage', 'Transportation & Delivery — Founder Skill Fit', '[]'::jsonb, '["Count your failed first attempts for one week, by area.", "Work out what re-attempting them cost.", "Fix the worst area -- a time window, a phone call before arrival."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["A second attempt costs nearly as much as the first and earns nothing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
