insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-302', 'The Founder Is Dispatch, Rider Support and Complaints', 'Founder Psychology', 'internal', 'A rider is lost, a parcel is missing, a customer is angry. The founder handles all of it all day, so the work that would make tomorrow calmer never begins.', 5, 9, '["Founder is dispatch and support", "Handles every complaint personally", "No time for process or growth", "The same problems every day"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-302-1', (select problem_id from problems where problem_code = 'DLV-302'), 'Answering Instead of Fixing', 'Behavioural', 'Each call is handled personally and the reason the calls keep coming is never addressed.', 0.77, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-302-2', (select problem_id from problems where problem_code = 'DLV-302'), 'No Hours Reserved', 'Operational', 'No time is protected for process or planning, so only the ringing phone gets attention.', 0.72, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-302-3', (select problem_id from problems where problem_code = 'DLV-302'), 'Being Reachable Feels Like Service', 'Psychological', 'The founder believes customers stay because they can always reach them, so stepping back feels like losing them.', 0.67, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-302-1', (select problem_id from problems where problem_code = 'DLV-302'), '["RC-DLV-302-1", "RC-DLV-302-2", "RC-DLV-302-3"]'::jsonb, 'Founder Leverage', 'Transportation & Delivery — Founder Time Use', '[]'::jsonb, '["Write down every call for one week and what it was about.", "Group them and fix the biggest group -- a tracking link, a written update rule, a second dispatcher.", "Count that group again next week."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["A call that repeats is a missing process, not a busy phone.", "Count before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-302-2', (select problem_id from problems where problem_code = 'DLV-302'), '["RC-DLV-302-1", "RC-DLV-302-2", "RC-DLV-302-3"]'::jsonb, 'Founder Leverage', 'Transportation & Delivery — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Hand dispatch to one person with the rules written down."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["Dispatch is a rules job once the rules exist."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
