insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-303', 'The Routes and the Riders Only Work Because of the Founder', 'Founder Psychology', 'internal', 'Which rider is reliable, which area needs two attempts, what each customer was promised — all unwritten. Nothing runs without the founder and a second city is impossible.', 5, 9, '["Route knowledge unwritten", "Rider reliability known only to the founder", "Customer promises not recorded", "Second city impossible"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-303-1', (select problem_id from problems where problem_code = 'DLV-303'), 'Route and Rider Knowledge Never Written', 'Knowledge', 'Which rider suits which area, and what each customer was promised, lives in the founder''s head.', 0.78, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-303-2', (select problem_id from problems where problem_code = 'DLV-303'), 'Relationships Not Transferred', 'Operational', 'Riders and customers deal with the founder personally and nobody else has the standing.', 0.73, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-303-3', (select problem_id from problems where problem_code = 'DLV-303'), 'Holding It Feels Like Control', 'Psychological', 'Keeping it all in one head feels like keeping standards, so writing it down feels like a loss of grip.', 0.66, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-303-1', (select problem_id from problems where problem_code = 'DLV-303'), '["RC-DLV-303-1", "RC-DLV-303-2", "RC-DLV-303-3"]'::jsonb, 'Founder Leverage', 'Transportation & Delivery — Founder Dependency', '[]'::jsonb, '["Write one page per route: which areas, what time windows, what goes wrong.", "Write one line per rider: what they are good at and what they are not.", "Let someone else plan tomorrow''s routes from those pages and check afterwards."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["Route knowledge on paper is what lets a second person plan a day.", "Check the plan afterwards, not before."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-303-2', (select problem_id from problems where problem_code = 'DLV-303'), '["RC-DLV-303-1", "RC-DLV-303-2", "RC-DLV-303-3"]'::jsonb, 'Founder Leverage', 'Transportation & Delivery — Founder Dependency', '[]'::jsonb, '["List what each customer was actually promised: windows, proof of delivery, escalation.", "Put it where dispatch can read it.", "Confirm it with your three biggest customers in writing."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["A promise only you remember is a dispute waiting to happen."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
