insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-304', 'Dispatch, Rider Management and Complaints Land on Anyone', 'Team & Leadership', 'internal', 'Nobody owns dispatch, nobody owns the riders and nobody owns a complaint. So a missing parcel gets three people and a rider who keeps failing gets none.', 5, 9, '["No owner for dispatch or riders", "Complaints handled by whoever answers", "Failing riders unmanaged", "Nobody accountable for a missed delivery"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-304-1', (select problem_id from problems where problem_code = 'DLV-304'), 'Roles Never Set', 'Behavioural', 'The team grew by adding hands to whatever was urgent rather than by defining jobs.', 0.76, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-304-2', (select problem_id from problems where problem_code = 'DLV-304'), 'Everyone Handles Everything', 'Psychological', 'A team where anyone picks up anything feels responsive, which hides that nothing is owned.', 0.70, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-304-3', (select problem_id from problems where problem_code = 'DLV-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a parcel moves from pickup to route to proof of delivery was never agreed.', 0.69, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-304-1', (select problem_id from problems where problem_code = 'DLV-304'), '["RC-DLV-304-1", "RC-DLV-304-2", "RC-DLV-304-3"]'::jsonb, 'Team Effectiveness', 'Transportation & Delivery — Role Clarity', '[]'::jsonb, '["List the stages: pickup, sort, route, delivery, proof, exception.", "Put one name against each.", "Write what must be complete before each handover."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["One owner per stage, even if one person owns two.", "Parcels go missing at the handover, not inside the stage."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-304-2', (select problem_id from problems where problem_code = 'DLV-304'), '["RC-DLV-304-1", "RC-DLV-304-2", "RC-DLV-304-3"]'::jsonb, 'Team Effectiveness', 'Transportation & Delivery — Role Clarity', '[]'::jsonb, '["Name one person who owns rider performance.", "Agree what they watch weekly: failed attempts per rider.", "Review that list with them every week, by rider name."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["A failing rider nobody owns keeps failing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
