insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-305', 'Nobody Can Waive a Fee, Re-Attempt or Compensate', 'Team & Leadership', 'internal', 'Dispatch cannot waive a delivery fee, cannot authorise a third attempt and cannot compensate for a damaged parcel. The customer waits, and in this trade they simply use someone else tomorrow.', 5, 9, '["Cannot waive a fee", "Third attempts need approval", "No compensation authority", "Customers switch provider"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-305-1', (select problem_id from problems where problem_code = 'DLV-305'), 'Limits Never Written', 'Operational', 'No amount has been written down that dispatch may waive or compensate, so nothing is resolved at first contact.', 0.78, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
