insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-305-3', (select problem_id from problems where problem_code = 'DLV-305'), 'Cost of Switching Not Counted', 'Knowledge', 'The value of a customer who stays has never been compared to the cost of a waived fee.', 0.67, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
