insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-307', 'Wants Contracted Business Customers, Lives on Ad-Hoc Jobs', 'Strategy & Planning', 'internal', 'The founder talks about contracted business volume. The work is ad-hoc jobs taken on the day, because they pay this week, and nothing about how the business runs would satisfy a contract customer.', 5, 9, '["Wants contracts, lives on ad-hoc", "No delivery records to show", "No consistency to sell", "Contract business out of reach"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-307-1', (select problem_id from problems where problem_code = 'DLV-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds the job mix against the stated ambition, so the gap grows quietly.', 0.78, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-307-2', (select problem_id from problems where problem_code = 'DLV-307'), 'Ad-Hoc Pays This Week', 'Behavioural', 'A job taken today brings money now, so it always wins against building what a contract needs.', 0.73, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-307-3', (select problem_id from problems where problem_code = 'DLV-307'), 'Goal Never Described as Requirements', 'Knowledge', 'Contracted business was never written down as what a contract customer requires.', 0.67, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-307-1', (select problem_id from problems where problem_code = 'DLV-307'), '["RC-DLV-307-1", "RC-DLV-307-2", "RC-DLV-307-3"]'::jsonb, 'Strategic Focus', 'Transportation & Delivery — Plan and Vision', '[]'::jsonb, '["Write what a contract customer needs before they sign: on-time figures, proof of delivery, capacity, insurance.", "Mark which you have.", "Build the missing one that takes longest, starting now."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["A contract is a list of requirements, not a bigger relationship.", "Start with the slowest missing piece."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-307-2', (select problem_id from problems where problem_code = 'DLV-307'), '["RC-DLV-307-1", "RC-DLV-307-2", "RC-DLV-307-3"]'::jsonb, 'Strategic Focus', 'Transportation & Delivery — Plan and Vision', '[]'::jsonb, '["List last month''s jobs and mark each repeat or one-off.", "Work out the share that was repeat.", "Decide the share you want and quote accordingly."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["Decide the mix on purpose rather than discovering it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
