insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-308', 'More Riders, a New City and an App, While Deliveries Fail', 'Strategy & Planning', 'internal', 'Three projects are running while the first-attempt failure rate goes unaddressed. That failure rate is what decides whether any of the three is affordable, and nobody is on it.', 5, 9, '["Several projects at once", "Failure rate unaddressed", "Nobody owns the core problem", "Everything half-done"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-308-1', (select problem_id from problems where problem_code = 'DLV-308'), 'Nothing Ranked', 'Strategic', 'Projects are listed rather than ordered, so a daily cost leak competes with expansion.', 0.78, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-308-2', (select problem_id from problems where problem_code = 'DLV-308'), 'Growth Feels More Urgent Than Fixing', 'Psychological', 'A new city is exciting and failure rates are dull, so the dull one waits.', 0.73, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-DLV-308-3', (select problem_id from problems where problem_code = 'DLV-308'), 'The Leak Not Measured', 'Knowledge', 'Nobody has counted what failed attempts cost, so the urgency is not felt.', 0.68, 'internal', 'Stage 0→1', '["transport_delivery"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-DLV-308-1', (select problem_id from problems where problem_code = 'DLV-308'), '["RC-DLV-308-1", "RC-DLV-308-2", "RC-DLV-308-3"]'::jsonb, 'Strategic Focus', 'Transportation & Delivery — Prioritisation', '[]'::jsonb, '["Count your failed first attempts for a week and cost them.", "Put that number next to the cost of your three projects.", "Pause two of them and put someone on the failure rate this week."]'::jsonb, '[3, 4, 5]'::jsonb, '["transport_delivery"]'::jsonb, '["Fixing the drop you already have is cheaper than winning a new one.", "Put the two numbers side by side and the priority decides itself."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
