insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('DLV-309', 'Which Area Fails and Which Rider Was Trouble Is Not Written', 'Strategy & Planning', 'internal', 'Which areas always need two attempts, which rider had repeated complaints, what last festival week actually needed — all in memory. So the same area is quoted the same price and the same rider is rehired.', 5, 9, '["Area failure patterns not recorded", "Rider complaint history not tracked", "Peak weeks planned from memory", "Knowledge leaves with dispatchers"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["transport_delivery"]'::jsonb) on conflict (problem_code) do nothing;
